+  void computeExactLiveOut(CgFunction &Func, unsigned NumRegs) {
+    BlockIndex.clear();
+    ExactLiveOut.clear();
+    // Bounded research experiment: fall back to existing conservative queries.
+    if (!std::getenv("DTVM_RESEARCH_EXACT_LIVEOUT") || NumRegs > 2048)
+      return;
+    unsigned Count = 0;
+    for (const auto *BB : Func) {
+      if (++Count > 256) return;
+    }
+    SmallVector<BitVector, 32> Uses, Defs, LiveIn;
+    for (const auto *BB : Func) {
+      BlockIndex[BB] = Uses.size();
+      BitVector Use(NumRegs), Def(NumRegs);
+      for (const auto &MI : *BB) {
+        // Read all operands before applying full definitions (tied operands).
+        for (const auto &MO : MI) {
+          if (!MO.isReg() || !MO.getReg().isVirtual()) continue;
+          unsigned R = Register::virtReg2Index(MO.getReg());
+          if ((MO.readsReg() || (MO.isDef() && MO.getSubReg())) && !Def.test(R))
+            Use.set(R);
+        }
+        for (const auto &MO : MI) {
+          if (MO.isReg() && MO.getReg().isVirtual() && MO.isDef() &&
+              !MO.getSubReg())
+            Def.set(Register::virtReg2Index(MO.getReg()));
+        }
+      }
+      Uses.push_back(std::move(Use));
+      Defs.push_back(std::move(Def));
+      LiveIn.emplace_back(NumRegs);
+      ExactLiveOut.emplace_back(NumRegs);
+    }
+    for (unsigned Iter = 0; Iter < 32; ++Iter) {
+      bool Changed = false;
+      for (const auto *BB : llvm::reverse(Func)) {
+        unsigned I = BlockIndex.lookup(BB);
+        BitVector Out(NumRegs);
+        for (const auto *Succ : BB->successors()) Out |= LiveIn[BlockIndex.lookup(Succ)];
+        BitVector In = Out;
+        In.reset(Defs[I]);
+        In |= Uses[I];
+        Changed |= In != LiveIn[I] || Out != ExactLiveOut[I];
+        LiveIn[I] = std::move(In);
+        ExactLiveOut[I] = std::move(Out);
+      }
+      if (!Changed) return;
+    }
+    // An incomplete fixed point is an underapproximation: never use it.
+    ExactLiveOut.clear();
+    BlockIndex.clear();
+  }

