+  void forwardSpillReloads(CgFunction &Func, unsigned NumRegs) {
+    if (!std::getenv("DTVM_RESEARCH_FORWARD_SPILLS") || NumRegs > 2048)
+      return;
+    unsigned Blocks = 0;
+    for (auto *BB : Func) if (++Blocks > 256) return;
+    struct Value { int FI; unsigned Reg; bool FromEntry; };
+    using Values = SmallVector<Value, 16>;
+    DenseMap<const CgBasicBlock *, Values> EndStates;
+    unsigned Removed = 0;
+    BitVector Preserved(TRI->getNumRegs());
+    auto IsFull64 = [&](unsigned Reg) {
+      return TRI->getRegSizeInBits(*TRI->getMinimalPhysRegClass(Reg)) == 64;
+    };
+    for (auto *BB : Func) {
+      Values Known;
+      if (BB->pred_size() == 1) {
+        auto It = EndStates.find(*BB->pred_begin());
+        if (It != EndStates.end()) {
+          Known = It->second;
+          for (auto &V : Known) V.FromEntry = true;
+        }
+      }
+      for (auto It = BB->begin(); It != BB->end();) {
+        auto &MI = *It++;
+        int LoadFI = 0, StoreFI = 0;
+        unsigned LoadBytes = 0, StoreBytes = 0;
+        unsigned LoadReg = _llvm_workaround->isLoadFromStackSlot(*TII, MI, LoadFI, LoadBytes);
+        unsigned StoreReg = _llvm_workaround->isStoreToStackSlot(*TII, MI, StoreFI, StoreBytes);
+        bool Load = LoadReg && LoadBytes == 8 && IsFull64(LoadReg) && MFI->isSpillSlotObjectIndex(LoadFI);
+        bool Store = StoreReg && StoreBytes == 8 && IsFull64(StoreReg) && MFI->isSpillSlotObjectIndex(StoreFI);
+        if (Load && llvm::any_of(Known, [&](const Value &V) { return V.FI == LoadFI && V.Reg == LoadReg; })) {
+          auto V = llvm::find_if(Known, [&](const Value &V) { return V.FI == LoadFI && V.Reg == LoadReg; });
+          if (V->FromEntry && !BB->isLiveIn(LoadReg)) BB->addLiveIn(LoadReg);
+          Preserved.set(LoadReg);
+          BB->erase(&MI);
+          ++Removed;
+          continue;
+        }
+        if (MI.isCall() || MI.isInlineAsm() || MI.hasUnmodeledSideEffects() || (MI.mayStore() && !Store)) {
+          Known.clear();
+          continue;
+        }
+        for (const auto &MO : MI) {
+          if (MO.isReg() && MO.isDef() && MO.getReg().isPhysical()) {
+            llvm::erase_if(Known, [&](const Value &V) { return TRI->regsOverlap(V.Reg, MO.getReg()); });
+          } else if (MO.isRegMask()) {
+            llvm::erase_if(Known, [&](const Value &V) { return MO.clobbersPhysReg(V.Reg); });
+          }
+        }
+        if (Load || Store) {
+          int FI = Load ? LoadFI : StoreFI;
+          unsigned Reg = Load ? LoadReg : StoreReg;
+          llvm::erase_if(Known, [&](const Value &V) { return V.FI == FI; });
+          if (Known.size() == 64) Known.clear();
+          Known.push_back({FI, Reg, false});
+        }
+      }
+      EndStates[BB] = std::move(Known);
+    }
+    if (Removed) {
+      for (auto *BB : Func)
+        for (auto &MI : *BB)
+          for (int R = Preserved.find_first(); R >= 0; R = Preserved.find_next(R))
+            MI.clearRegisterKills(R, TRI);
+    }
+    if (std::getenv("DTVM_RESEARCH_SPILL_LOG"))
+      std::fprintf(stderr, "FORWARD_SPILLS %u %u\n", NumRegs, Removed);
+  }
